# Vorschlagsseite (noindex): immer NUR die aktuelle Runde, nie alte Listen mitliefern (Noah, 15.11.2026).
# Runde 7 (Noah mochte 6, 9, 20: Servus ich bin Noah + Brüder/Handwerksfirmen + ich weiß, wie es zugeht + abends keine Lust). Runde 6 (Aufbau nach Noah: Intro, Überleitung, einer der drei Familiensätze, Outro; Vorbild Felix auf zimmerei-partner.de, kürzer). Runde 5 (Runde 4 war Noah zu unauthentisch, Werbetexter-Sätze): Noahs eigene Sätze aus den Calls als Vorlage. Runde 4: komplette Über-uns-Sektionen (kleine Zeile, Überschrift, Text), HWM persönlich, SHK ohne Persönliches.
from pathlib import Path
import html
N = 'Noah Seelau, Gründer'
BLOECKE = [('Handwerksmanufaktur · Texte', 'fünf verschiedene Fassungen', [('Text', '', 'Servus, ich bin Noah. Ich hab die Handwerksmanufaktur 2019 gegründet. Zum Handwerk hab ich einen kurzen Weg. Zwei meiner Brüder sind im Handwerk, und wir haben in der Familie mehrere Handwerksfirmen. Daher weiß ich, wie es in den Betrieben zugeht. Seit 2019 kümmern wir uns für Handwerksbetriebe um Website, Aufträge und Mitarbeiter. Über 150 Betriebe haben wir bisher betreut.', ''), ('Text', '', 'Ich bin Noah, der Gründer der Handwerksmanufaktur. Dass wir nur fürs Handwerk arbeiten, kommt nicht von ungefähr. Zwei von meinen Brüdern arbeiten im Handwerk, und bei uns in der Familie gibt es gleich mehrere Handwerksbetriebe. Ich kriege also seit Jahren mit, was in so einem Betrieb los ist. Genau deshalb machen wir seit 2019 nichts anderes. Mehr als 150 Betriebe haben in der Zeit mit uns gearbeitet.', ''), ('Text', '', 'Hallo, ich bin Noah. Handwerk war bei uns in der Familie schon immer da. Es gibt mehrere Handwerksfirmen, und zwei meiner Brüder sind selbst im Handwerk gelandet. Wie es in einem Betrieb läuft, muss mir deshalb keiner erklären. 2019 hab ich daraus meinen Beruf gemacht und die Handwerksmanufaktur gegründet. Heute bauen wir Websites und bringen Betrieben Aufträge und Mitarbeiter. Inzwischen sind es über 150.', ''), ('Text', '', 'Servus, Noah hier. Die Handwerksmanufaktur gibt es seit 2019, und seitdem arbeiten wir ausschließlich mit Handwerksbetrieben. Warum? In meiner Familie gibt es mehrere Handwerksfirmen, und zwei meiner Brüder sind selbst Handwerker. Ich weiß also ziemlich genau, wie der Alltag in einem Betrieb aussieht. Darum kümmern wir uns um das, wofür dort keine Zeit bleibt: Website, Aufträge und Mitarbeiter.', ''), ('Text', '', 'Ich bin Noah und hab 2019 die Handwerksmanufaktur gegründet. Das Handwerk kenne ich schon mein ganzes Leben. Bei uns gibt es mehrere Handwerksfirmen in der Familie, und zwei meiner Brüder haben dort ihren Platz gefunden. Deshalb verstehe ich, worum es in einem Betrieb geht und was dort gebraucht wird. Wir sorgen dafür, dass du online gefunden wirst, Aufträge bekommst und gute Leute findest. Das machen wir seit acht Jahren und nur fürs Handwerk.', '')]), ('Handwerksmanufaktur · Überschriften', 'frei kombinierbar', [('Überschrift', 'Wer hinter der Handwerksmanufaktur steht.', '', ''), ('Überschrift', 'Seit 2019 nur fürs Handwerk.', '', ''), ('Überschrift', 'Mit wem du es zu tun hast.', '', ''), ('Überschrift', 'Der Kopf hinter der Handwerksmanufaktur.', '', ''), ('Überschrift', 'Handwerk kenne ich von daheim.', '', ''), ('Überschrift', 'Ein Gesicht zur Handwerksmanufaktur.', '', ''), ('Überschrift', 'Acht Jahre. Nur Handwerk.', '', ''), ('Überschrift', 'Der Gründer.', '', ''), ('Überschrift', 'Wer wir sind.', '', ''), ('Überschrift', 'Seit 2019 an der Seite des Handwerks.', '', '')]), ('SHK · Texte', 'gleicher Aufbau', [('Text', '', 'Servus, ich bin Noah, Gründer der Handwerksmanufaktur. Zum Handwerk hab ich einen kurzen Weg. Zwei meiner Brüder sind im Handwerk, und wir haben in der Familie mehrere Handwerksfirmen. Daher weiß ich, wie es in den Betrieben zugeht. Für SHK-Betriebe holen wir Monteure und Aufträge für Bad und Wärmepumpe. Über 150 Handwerksbetriebe haben wir bisher betreut.', ''), ('Text', '', 'Ich bin Noah und hab die Handwerksmanufaktur gegründet. Dass wir fürs Handwerk arbeiten, kommt nicht von ungefähr. Zwei von meinen Brüdern arbeiten im Handwerk, und bei uns in der Familie gibt es gleich mehrere Handwerksbetriebe. Ich kriege also seit Jahren mit, was in so einem Betrieb los ist. Für SHK-Betriebe sorgen wir dafür, dass Monteure und Aufträge planbar kommen.', ''), ('Text', '', 'Hallo, ich bin Noah. Handwerk war bei uns in der Familie schon immer da. Es gibt mehrere Handwerksfirmen, und zwei meiner Brüder sind selbst im Handwerk gelandet. Wie es in einem Betrieb läuft, muss mir deshalb keiner erklären. Seit acht Jahren mache ich Marketing nur fürs Handwerk. Bei SHK-Betrieben heißt das: Monteure finden und Aufträge für Bad und Wärmepumpe holen.', ''), ('Text', '', 'Servus, Noah hier. Wir arbeiten seit 8 Jahren ausschließlich mit Handwerksbetrieben. Warum? In meiner Familie gibt es mehrere Handwerksfirmen, und zwei meiner Brüder sind selbst Handwerker. Ich weiß also ziemlich genau, wie der Alltag in einem Betrieb aussieht. Darum nehmen wir SHK-Betrieben ab, wofür dort keine Zeit bleibt: Monteure suchen und Aufträge aus dem Umkreis holen.', ''), ('Text', '', 'Ich bin Noah, und das Handwerk kenne ich schon mein ganzes Leben. Bei uns gibt es mehrere Handwerksfirmen in der Familie, und zwei meiner Brüder haben dort ihren Platz gefunden. Deshalb verstehe ich, worum es in einem Betrieb geht und was dort gebraucht wird. Mit der Handwerksmanufaktur holen wir für SHK-Betriebe Monteure und Aufträge aus dem Umkreis. Mehr als 150 Handwerksbetriebe haben schon mit uns gearbeitet.', '')]), ('SHK · Überschriften', 'frei kombinierbar', [('Überschrift', 'Wer hinter der Handwerksmanufaktur steht.', '', ''), ('Überschrift', 'Seit 8 Jahren nur fürs Handwerk.', '', ''), ('Überschrift', 'Mit wem du es zu tun hast.', '', ''), ('Überschrift', 'Wer dahinter steht.', '', ''), ('Überschrift', 'Dein Ansprechpartner.', '', ''), ('Überschrift', 'Du beherrschst dein Handwerk. Wir unseres.', '', ''), ('Überschrift', 'Handwerk kenne ich von daheim.', '', ''), ('Überschrift', 'Der Partner für SHK-Betriebe.', '', ''), ('Überschrift', 'Der Gründer.', '', ''), ('Überschrift', 'Wer wir sind.', '', '')])]
e = html.escape
def h(x):
    a, _, b = x.partition('|')
    return e(a) + (f'<br><em>{e(b)}</em>' if b else '')
out = ['<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Über-uns-Texte</title><style>'
 ':root{--ink:#0B1424;--sub:#4A5666;--line:#DCE3EC;--paper:#F3F6FA;--warm:#C9581A}*{box-sizing:border-box;margin:0;padding:0}body{background:var(--paper);color:var(--ink);font:17px/1.55 Inter,system-ui,-apple-system,sans-serif;-webkit-font-smoothing:antialiased}'
 '.wrap{max-width:760px;margin:0 auto;padding:32px 20px 96px}h1{font-size:clamp(30px,5vw,44px);letter-spacing:-.03em;line-height:1.1;margin-bottom:8px}.lead{color:var(--sub)}h2{font-size:24px;letter-spacing:-.02em;margin:56px 0 16px}h2 small{display:block;font-size:15px;font-weight:400;letter-spacing:0;color:var(--sub);margin-top:4px}'
 '.k{background:#fff;border:1px solid var(--line);border-radius:24px;padding:32px;margin-bottom:16px;position:relative}.nr{position:absolute;top:28px;right:32px;font-size:15px;font-weight:600;color:var(--sub)}.kl{font-size:14px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--warm);margin-bottom:16px}'
 '.k h3{font-size:clamp(28px,5vw,38px);line-height:1.1;letter-spacing:-.03em;margin-bottom:20px;text-wrap:balance}.k h3 em{font-style:italic;font-weight:500;color:var(--warm)}.k p{color:var(--sub);max-width:58ch}.k .sig{margin-top:20px;color:var(--ink);font-weight:600;font-size:15px}'
 '@media(max-width:560px){.k{padding:24px 20px}.nr{top:20px;right:20px}}'
 '</style></head><body><div class="wrap"><h1>Über-uns-Texte</h1><p class="lead">Nenn mir Seite und Nummer.</p>']
for titel, dom, liste in BLOECKE:
    out.append(f'<h2>{e(titel)}<small>{e(dom)}</small></h2>')
    for i, (kl, hh, tx, sig) in enumerate(liste, 1):
        out.append(f'<div class="k"><span class="nr">{i}</span><div class="kl">{e(kl)}</div>' + (f'<h3 style="margin-bottom:0">{h(hh)}</h3>' if hh else '') + (f'<p>{e(tx)}</p>' if tx else '') + (f'<p class="sig">{e(sig)}</p>' if sig else '') + '</div>')
out.append('</div></body></html>')
s = ''.join(out)
assert '–' not in s and '—' not in s and 'sondern' not in s and 'komme aus einer' not in s and 'keine Lust' not in s
Path(__file__).with_name('index.html').write_text(s)
print(sum(len(l) for _, _, l in BLOECKE), 'Texte')
